<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {RefreshCw,FolderOpen,Search,List,LayoutGrid} from 'lucide-svelte';
 import FileResults from './FileResults.svelte';
 import {mergeFiles,fileLocation,filterFiles,fileFilters,type DriveItem,type FilesPage} from './files';
 let {ownId,isLive,initialItem=null,onNavigationHandled=()=>{}}:{ownId:string;isLive:boolean;initialItem?:DriveItem|null;onNavigationHandled?:()=>void}=$props();
 let rows=$state<DriveItem[]>([]),next=$state<string|null>(null),busy=$state(false),error=$state(''),query=$state(''),applied=$state(''),sort=$state('name'),selected=$state('');
 function savedView():'list'|'icons'{try{return localStorage.getItem('taut.files.view.v1')==='icons'?'icons':'list';}catch{return 'list';}}
 let view=$state<'list'|'icons'>(savedView()),filter=$state('all');
 $effect(()=>{try{localStorage.setItem('taut.files.view.v1',view);}catch{}});
 let trail=$state<{id:string|null;name:string}[]>([{id:null,name:'My OneDrive'}]);let alive=true,serial=0;
 const sorted=$derived([...filterFiles(rows,filter)].sort((a,b)=>Number(b.folder)-Number(a.folder)||(sort==='modified'?(b.modified??'').localeCompare(a.modified??''):a.name.localeCompare(b.name))));
 async function load(more=false){const version=++serial;busy=true;error='';try{const result=await invoke<FilesPage>('files_page',{query:{folder:applied?null:trail.at(-1)!.id,search:applied||null,next:more?next:null}});if(!alive||version!==serial)return;rows=more?mergeFiles(rows,result.value):result.value;next=result.next;}catch(e){if(alive&&version===serial)error=String(e);}finally{if(alive&&version===serial)busy=false;}}
 function navigate(index:number){trail=trail.slice(0,index+1);applied='';query='';rows=[];next=null;selected='';void load();}
 function locate(item:DriveItem){if(item.shortcut){error='This is a shared shortcut. Use Open to view it in OneDrive.';return;}if(item.folder){trail=applied?[trail[0],{id:item.id,name:item.name}]:[...trail,{id:item.id,name:item.name}];applied='';query='';rows=[];next=null;selected='';void load();}else selected=item.id;}
 function search(){applied=query.trim();rows=[];next=null;selected='';void load();}
 onMount(()=>{if(initialItem){const item=initialItem;const id=item.folder?item.id:item.parentId;if(id)trail=[trail[0],{id,name:item.folder?item.name:fileLocation(item).split('/').filter(Boolean).at(-1)||'Containing folder'}];selected=item.id;onNavigationHandled();}if(isLive)void load();});
 onDestroy(()=>{alive=false;serial++;});
</script>
<section class="files-workspace" aria-label="Files"><header><div><div class="eyebrow">YOUR FILES, WITHIN REACH</div><h1>Files</h1><p>Browse your OneDrive. Downloads are saved only where you choose.</p></div><button aria-label="Refresh OneDrive" disabled={busy||!isLive} onclick={()=>load()}><RefreshCw size={18}/></button></header>
<div class="toolbar"><nav aria-label="OneDrive folders">{#each trail as folder,i}<button disabled={busy} aria-current={!applied&&i===trail.length-1?'page':undefined} onclick={()=>navigate(i)}>{folder.name}</button>{#if i<trail.length-1}<span>/</span>{/if}{/each}</nav><form onsubmit={event=>{event.preventDefault();search();}}><Search size={15}/><input aria-label="Search OneDrive" bind:value={query} maxlength="500" placeholder="Search all of My OneDrive"/><button disabled={busy||!isLive}>Search</button></form></div>
<div class="contents">{#if !isLive}<p>Connect Microsoft 365 to browse your OneDrive.</p>{:else}
 {#if applied}<h2>OneDrive results for “{applied}”</h2><button onclick={()=>navigate(trail.length-1)} disabled={busy}>Back to folder</button>{/if}
 <div class="list-heading"><span>{filter==='all'?`${rows.length} items loaded`:`${sorted.length} of ${rows.length} loaded items shown`}{next?' · more available':''}</span><div class="file-controls"><div class="views" role="group" aria-label="Files view"><button aria-label="List view" aria-pressed={view==='list'} onclick={()=>view='list'}><List size={16}/><span>List</span></button><button aria-label="Icons view" aria-pressed={view==='icons'} onclick={()=>view='icons'}><LayoutGrid size={16}/><span>Icons</span></button></div><label>Filter loaded items<select aria-label="Filter loaded items" bind:value={filter}>{#each fileFilters as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Sort loaded items<select aria-label="Sort loaded items" bind:value={sort}><option value="name">Name A–Z</option><option value="modified">Recently modified</option></select></label></div></div>
 {#if error}<p role="alert">{error}</p><button disabled={busy} onclick={()=>load(!!rows.length&&!!next)}>Try again</button>{/if}
 <FileResults {view} items={sorted} {ownId} {selected} onLocate={locate} search={!!applied}/>
 {#if busy}<p role="status">Loading OneDrive…</p>{:else if !rows.length&&!error}<div class="empty"><FolderOpen size={40}/><h2>{applied?'No matching files':'This folder is empty'}</h2></div>{/if}
 {#if !busy&&rows.length&&!sorted.length}<p>No loaded items match this type.{next?' Load more files to check additional items.':''}</p>{/if}
 {#if next}<button class="more" disabled={busy} onclick={()=>load(true)}>Load more files</button>{/if}<p class="hint">Downloads up to 100 MB. Larger files and shared shortcuts can be opened in OneDrive. Uploads and in-app previews are coming later.</p>
{/if}</div></section>
<style>
.file-controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.views{display:flex;gap:4px}.views button{display:flex;align-items:center;gap:6px;font-size:12px}.views button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}.list-heading{flex-wrap:wrap}
.files-workspace{flex:1;min-width:0;display:flex;flex-direction:column;color:var(--text-primary)}header{display:flex;justify-content:space-between;align-items:center;padding:28px;border-bottom:1px solid var(--border);background:var(--surface-panel)}h1{margin:8px 0;font-size:28px}header p{font-size:12px;color:var(--text-secondary)}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent);font-weight:700}button,select,input{font:inherit;color:var(--text-primary)}button{cursor:pointer;padding:8px 12px;border:1px solid var(--border-strong);border-radius:7px}button:disabled{opacity:.5;cursor:default}.toolbar{display:flex;gap:16px;flex-wrap:wrap;justify-content:space-between;padding:16px 28px;border-bottom:1px solid var(--border)}nav{display:flex;align-items:center;gap:8px;flex-wrap:wrap}nav button{font-size:12px;color:var(--accent)}form{display:flex;align-items:center;gap:8px}input,select{min-width:0;border:1px solid var(--border-strong);background:var(--surface-panel);padding:8px;border-radius:6px;font-size:12px}.contents{padding:24px 28px;overflow:auto;flex:1;min-height:0}.list-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px;font-size:12px;color:var(--text-secondary)}label{display:flex;gap:8px;align-items:center}.hint{font-size:11px;line-height:1.7;color:var(--text-secondary);margin-top:20px}.empty{text-align:center;padding:50px;color:var(--text-secondary)}.more{margin-top:18px}[role=alert]{color:var(--error)}h2{font-size:18px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}</style>
